<style>
.cart-shell,.cart-shell *{box-sizing:border-box}.cart-shell{font-family:Arial,sans-serif}
.cart-shell{padding:20px;max-width:1800px;margin:auto;color:#19394b;font-size:14px}.cart-hero{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:24px;background:linear-gradient(115deg,#075771,#128d8b);color:#fff;border-radius:16px;margin-bottom:18px}.cart-hero h1{font-size:26px;margin:5px 0}.cart-hero p{margin:0;opacity:.94}.cart-card{background:#fff;border:1px solid #d7e3ea;border-radius:12px;padding:20px;margin-bottom:18px;box-shadow:0 4px 16px #183a4b08}.cart-toolbar{display:flex;gap:10px;align-items:end;flex-wrap:wrap}.cart-field{min-width:140px;flex:1}.cart-field label{display:block;font-weight:600;margin-bottom:5px}.cart-shell input,.cart-shell select,.cart-shell textarea{width:100%;border:1px solid #afc5d1;border-radius:6px;padding:9px;background:#fff;color:#183a4b}.cart-shell input[readonly]{background:#edf3f6}.cart-shell input:focus,.cart-shell select:focus,.cart-shell textarea:focus{outline:2px solid #128d8b;outline-offset:1px}.cart-btn{display:inline-flex;align-items:center;gap:7px;justify-content:center;background:#087c84;color:#fff!important;padding:10px 15px;border:0;border-radius:7px;font-weight:600;cursor:pointer;text-decoration:none!important;white-space:nowrap}.cart-btn.secondary{background:#e9f2f6;color:#164d63!important}.cart-btn.danger{background:#b73543}.cart-btn:disabled{opacity:.5;cursor:wait}.cart-scroll{overflow-x:auto}.cart-table{width:100%;border-collapse:collapse;font-size:13px}.cart-table th{background:#edf4f7;color:#214b60;text-align:left}.cart-table th,.cart-table td{border-bottom:1px solid #dce7ec;padding:11px 9px;vertical-align:top}.cart-table input{min-width:100px}.cart-table .cart-name{min-width:220px}.cart-muted{color:#577584;font-size:12px}.cart-badge{display:inline-block;padding:4px 8px;border-radius:5px;background:#e6f3ec;color:#226940;white-space:nowrap;font-size:12px}.cart-badge.warning{background:#fff1d3;color:#815309}.cart-badge.danger{background:#fee7e9;color:#9c2037}.cart-note{padding:13px 16px;background:#eaf4fb;border-left:4px solid #2c89b6;border-radius:5px;margin:14px 0}.cart-error{padding:14px;background:#fee7e9;border-left:4px solid #ad2940;margin:14px 0;color:#8a1d30}.cart-empty{padding:35px;text-align:center;color:#577584}.cart-summary{display:flex;gap:30px;flex-wrap:wrap}.cart-summary strong{display:block}.cart-matrix td,.cart-matrix th{border:1px solid #d7e3ea;padding:7px;text-align:center;min-width:32px}.cart-matrix td:first-child{min-width:240px;text-align:left;position:sticky;left:0;background:#fff}.cart-history{padding:12px;border-bottom:1px solid #dce7ec}.cart-history summary{cursor:pointer}.cart-foot{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-top:16px}.cart-shell .pagination{margin:15px 0;display:flex;gap:3px}.cart-shell .pagination li{list-style:none}.cart-shell .pagination a,.cart-shell .pagination span{display:block;padding:7px 12px;border:1px solid #d7e3ea;border-radius:5px}.cart-shell .pagination .active span{background:#087c84;color:#fff}@media(max-width:760px){.cart-shell{padding:12px}.cart-hero{padding:18px;display:block}.cart-hero .cart-toolbar{margin-top:15px}.cart-card{padding:14px}.cart-field{min-width:45%}.cart-foot{align-items:start;flex-direction:column}}
</style>
